//! A miniature error type that renders like a chain of contexts.
//!
//! The topmost message is printed on the `zoxide: ` line, everything below it
//! is listed under `Caused by:`.

use std::fmt::Display;
use std::result;

#[derive(Debug)]
pub struct Error {
    chain: Vec<String>,
}

pub type Result<T> = result::Result<T, Error>;

impl Error {
    /// A standalone message with no underlying cause.
    pub fn msg(message: impl Display) -> Self {
        Self { chain: vec![message.to_string()] }
    }

    /// Wraps this error in an outer explanation.
    pub fn context(mut self, message: impl Display) -> Self {
        self.chain.insert(0, message.to_string());
        self
    }

    pub fn report(&self) -> String {
        let mut out = format!("zoxide: {}\n", self.chain[0]);
        let causes = &self.chain[1..];
        match causes {
            [] => {}
            [only] => out.push_str(&format!("\nCaused by:\n    {only}\n")),
            many => {
                out.push_str("\nCaused by:\n");
                for (idx, cause) in many.iter().enumerate() {
                    out.push_str(&format!("    {idx}: {cause}\n"));
                }
            }
        }
        out
    }
}

/// Attaches an explanation to a failed operation, keeping the original error
/// as a cause.
pub trait Context<T> {
    fn context(self, message: impl Display) -> Result<T>;
}

impl<T, E: Display> Context<T> for result::Result<T, E> {
    fn context(self, message: impl Display) -> Result<T> {
        self.map_err(|err| Error { chain: vec![message.to_string(), err.to_string()] })
    }
}

impl<T> Context<T> for Option<T> {
    fn context(self, message: impl Display) -> Result<T> {
        self.ok_or_else(|| Error::msg(message))
    }
}

/// Why the process is terminating.
pub enum Exit {
    /// Print the report on stderr and exit with 1.
    Failure(Error),
    /// Exit with the given code without printing anything.
    Quiet(i32),
}

impl From<Error> for Exit {
    fn from(err: Error) -> Self {
        Self::Failure(err)
    }
}

macro_rules! bail {
    ($($arg:tt)*) => {
        return ::std::result::Result::Err($crate::error::Error::msg(format!($($arg)*)).into())
    };
}
pub(crate) use bail;

